import java.util.Scanner

fun main() {
    val sc = Scanner(System.`in`)
    val cs = Array(20) { Array(8) { CharArray(8) } }
    for (i in 0..7) {
        cs[0][i] = sc.next().toCharArray()
    }

    for (i in 0..18) {
        for (y in 0..7) {
            for (x in 0..7) {
                if (cs[i][y][x] == 'M') {
                    for (dy in -1..1) {
                        for (dx in -1..1) {
                            val xx = x + dx
                            val yy = y + dy
                            if (xx in 0..7 && yy in 0..7 && cs[i][yy][xx] != 'S') {
                                cs[i + 1][yy][xx] = 'M'
                            }
                        }
                    }
                }
            }
        }

        for (y in 6 downTo 0) {
            for (x in 0..7) {
                if (cs[i][y][x] == 'S') {
                    cs[i + 1][y + 1][x] = 'S'
                }
            }
        }
    }

    var res = "LOSE"
    for (y in 0..7) {
        for (x in 0..7) {
            if (cs[19][y][x] == 'M') {
                res = "WIN"
            }
        }
    }
    println(res)
}

